}

function getDailyBallSpeedScale(): number {
  if (activeDailyMods.some(m => m.id === 'fast_ball')) return 1.5;
  return 1.0;
}

function getDailySpinScale(): number {
  if (activeDailyMods.some(m => m.id === 'spin_madness')) return 2.0;
  return 1.0;
}

